// src/pages/Profile.js

import { FiSettings } from "react-icons/fi";

import { useNavigate } from "react-router-dom";

const books = [
  {
    title: "노르웨이의 숲",
    review:
      "상실 이후에도 사람은 계속 살아간다는 점이 가장 인상 깊었다. 와타나베의 감정선이 잔잔하게 이어지는 느낌이 좋았다.",
  },

  {
    title: "데미안",
    review:
      "자기 자신을 찾아가는 과정이 정말 인상 깊었다. 성장이라는 게 결국 내 안을 마주하는 일이라는 생각이 들었다.",
  },

  {
    title: "어린왕자",
    review:
      "어른이 된다는 건 무엇일까 다시 생각하게 만든 책이었다. 단순하지만 오래 남는 문장들이 많았다.",
  },

  {
    title: "1984",
    review:
      "감시 사회의 무서움을 현실적으로 보여줘서 몰입감이 강했다. 자유에 대해 다시 생각하게 됐다.",
  },

  {
    title: "해변의 카프카",
    review:
      "현실과 환상이 섞이는 분위기가 매력적이었다. 읽고 난 뒤에도 여운이 길게 남았다.",
  },

  {
    title: "채식주의자",
    review:
      "인물의 심리 변화가 굉장히 강렬했다. 불편하지만 계속 생각나게 되는 작품이었다.",
  },
];

function Profile() {
  const navigate = useNavigate();

  const currentUser = JSON.parse(
    localStorage.getItem(
      "currentUser"
    )
  );

  const userName =
    currentUser?.name || "READLY";

  return (
    <div className="page">
      {/* 상단 */}

      <div className="profile-header">
        <div className="logo">
          READLY
        </div>

        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}

      <div className="profile-top">
        <div className="profile-image"></div>

        <div className="profile-info">
          <div className="profile-name">
            {userName} ✏️
          </div>

          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">
                100
              </div>

              <div className="follow-text">
                팔로워
              </div>
            </div>

            <div className="follow-box">
              <div className="follow-num">
                100
              </div>

              <div className="follow-text">
                팔로잉
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 소개 */}

      <div className="profile-desc">
        에세이를 좋아하는 책린이 입니다!
        <br />
        instagram: xx_123
      </div>

      <div className="line"></div>

      {/* 책 스택 */}

      <div className="books-section">
        <div className="stack-message">
          현재 10.99cm만큼 쌓였어요!
          <br />
          조금 더 분발해요!
        </div>

        <div className="book-stack-wrap">
          <div className="shelf-top"></div>

          {books.map((book, index) => (
            <div
              className="book-item"
              key={index}
              onClick={() =>
                navigate("/review", {
                  state: {
                    title:
                      book.title,

                    review:
                      book.review,
                  },
                })
              }
              style={{
                cursor: "pointer",
              }}
            >
              {book.title}
            </div>
          ))}

          <div className="shelf"></div>
        </div>
      </div>
    </div>
  );
}

export default Profile;
